"""Copy Verge's docs from their code repositories into the site, as Zola pages.

    python3 .github/verge-docs.py SITE [--repo NAME=PATH ...]

SITE is this repository. The docs to copy, their order and their addresses are in
content/verge/_index.md's front matter. Each comes from a checkout of its repository: by default the
directory beside SITE with the repository's name, or the one --repo names. The pages go to
content/verge/docs/, which is generated and ignored by git.

A doc keeps reading on GitHub, so its links are relative links between files, or GitHub links to a
file in another repository. Here a link to a doc in the list, either way, becomes a link to that
doc's page (Zola's @/ link, which zola build checks), and a relative link to any other file becomes
a link to that file on GitHub. A file name that names a doc in the list, in a code span such as
`HOST-INTERFACE.md` or bare in the text, links the same way. An anchor is written as GitHub makes
it from a heading, and becomes the one Zola makes from the same heading: GitHub drops punctuation
("Past NXP's limits" is #past-nxps-limits), where Zola turns it into a dash (#past-nxp-s-limits).
The doc's first heading is its title, which the page prints itself, so it is dropped.

An SVG image from the doc's own repository, on a line of its own, is copied into the page as a
figure rather than linked, so the site's colours, fonts and day and night faces reach it. Its alt
text becomes the figure's accessible name.
"""
import argparse
import html
import json
import pathlib
import re
import shutil
import sys
import tomllib
import unicodedata

GITHUB = "https://github.com/Escapement-Project"
MARKER = "# Generated by .github/verge-docs.py; edit the docs in their repositories."

ap = argparse.ArgumentParser()
ap.add_argument("site", type=pathlib.Path)
ap.add_argument("--repo", action="append", default=[], metavar="NAME=PATH")
args = ap.parse_args()

index = (args.site / "content" / "verge" / "_index.md").read_text()
front = re.match(r"\+\+\+\n(.*?)\n\+\+\+", index, re.S)
if not front:
    sys.exit("content/verge/_index.md has no +++ front matter")
groups = tomllib.loads(front.group(1))["extra"]["groups"]
repos = {name: pathlib.Path(path) for name, path in (r.split("=", 1) for r in args.repo)}

def checkout(repo: str) -> pathlib.Path:
    return repos.get(repo) or args.site.resolve().parent / repo

docs = [dict(d, group=g["title"]) for g in groups for d in g["docs"]]
by_source = {(d["repo"], d["path"]): d for d in docs}

out = args.site / "content" / "verge" / "docs"
if out.exists():
    first = (out / "_index.md").read_text().splitlines()[1:2] if (out / "_index.md").exists() else []
    if first != [MARKER]:
        sys.exit(f"{out} exists and was not made by this script; move it away first")
    shutil.rmtree(out)
out.mkdir()
(out / "_index.md").write_text(
    f'+++\n{MARKER}\ntitle = "Docs"\nsort_by = "weight"\ntemplate = "verge-docs.html"\ninsert_anchor_links = "right"\n+++\n'
)

def heading_text(line: str) -> str:
    """A heading's text as it reads: code spans, links and emphasis reduced to their words."""
    text = re.sub(r"\[([^\]]*)\]\([^)]*\)", r"\1", line.lstrip("#").strip())
    return re.sub(r"[`*_]", "", text)

def github_slug(text: str) -> str:
    return re.sub(r"[^\w\- ]", "", text.lower()).replace(" ", "-")

def zola_slug(text: str) -> str:
    ascii_ = unicodedata.normalize("NFKD", text).encode("ascii", "ignore").decode().lower()
    return re.sub(r"[^a-z0-9]+", "-", ascii_).strip("-")

def anchors(text: str) -> dict[str, str]:
    """Each heading's GitHub anchor, mapped to Zola's for the same heading."""
    found, fenced = {}, False
    for line in text.splitlines():
        if line.lstrip().startswith("```"):
            fenced = not fenced
        elif not fenced and re.match(r"#{1,6} ", line):
            words = heading_text(line)
            found.setdefault(github_slug(words), zola_slug(words))
    return found

sources = {}
for doc in docs:
    file = checkout(doc["repo"]) / doc["path"]
    if file.is_file():
        sources[(doc["repo"], doc["path"])] = file.read_text()
headings = {key: anchors(text) for key, text in sources.items()}

def page(linked: dict, anchor: str) -> str:
    key = (linked["repo"], linked["path"])
    hash_ = f"#{headings.get(key, {}).get(anchor, anchor)}" if anchor else ""
    return f"@/verge/docs/{linked['name']}.md{hash_}"

def target(doc: dict, link: str) -> str:
    """Where a link in `doc` goes on the site: a doc's page, a file on GitHub, or as written."""
    elsewhere = re.fullmatch(re.escape(GITHUB) + r"/([\w.-]+)/blob/[^/]+/([^#]+)(?:#(.*))?", link)
    if elsewhere:
        linked = by_source.get((elsewhere[1], elsewhere[2]))
        if linked and (linked["repo"], linked["path"]) in sources:
            return page(linked, elsewhere[3] or "")
        return link
    if link.startswith("#"):
        return "#" + headings.get((doc["repo"], doc["path"]), {}).get(link[1:], link[1:])
    if re.match(r"[a-z][a-z0-9+.-]*:|/", link):
        return link
    path, _, anchor = link.partition("#")
    resolved = (pathlib.PurePosixPath(doc["path"]).parent / path).as_posix()
    # Collapse ./ and ../ without touching the filesystem.
    parts: list[str] = []
    for part in resolved.split("/"):
        if part == "..":
            parts and parts.pop()
        elif part not in ("", "."):
            parts.append(part)
    resolved = "/".join(parts)
    linked = by_source.get((doc["repo"], resolved))
    if linked and (linked["repo"], linked["path"]) in sources:
        return page(linked, anchor)
    hash_ = f"#{anchor}" if anchor else ""
    return f"{GITHUB}/{doc['repo']}/blob/HEAD/{resolved}{hash_}"

def figure(doc: dict, alt: str, link: str) -> str:
    root = checkout(doc["repo"]).resolve()
    file = (root / pathlib.PurePosixPath(doc["path"]).parent / link).resolve()
    if not file.is_relative_to(root) or not file.is_file():
        sys.exit(f"{doc['repo']}/{doc['path']}: no figure at {link}")
    svg = re.sub(r"\A<\?xml[^>]*>\s*", "", file.read_text())
    if not svg.startswith("<svg "):
        sys.exit(f"{doc['repo']}/{doc['path']}: {link} does not start with <svg")
    svg = svg.replace("<svg ", f'<svg role="img" aria-label="{html.escape(alt)}" ', 1)
    # A blank line would end Markdown's HTML block.
    body = "\n".join(line for line in svg.splitlines() if line.strip())
    return f'<figure class="diagram">\n{body}\n</figure>'

def rewrite(doc: dict, text: str) -> str:
    lines, fenced = [], False
    for line in text.splitlines():
        image = re.fullmatch(r"!\[([^\]]*)\]\(([^)\s#:]+\.svg)\)\s*", line)
        if line.lstrip().startswith("```"):
            fenced = not fenced
        elif not fenced and image and not image[2].startswith("/"):
            line = figure(doc, image[1], image[2])
        elif not fenced:
            line = re.sub(r"(\]\()([^)\s]+)(\))", lambda m: m[1] + target(doc, m[2]) + m[3], line)
            line = re.sub(r"(?<!\[)`([A-Z][A-Z0-9-]*\.md)`(?!\])",
                          lambda m: f"[`{m[1]}`]({target(doc, m[1])})" if (doc["repo"], m[1]) in sources else m[0], line)
            # A bare file name in the text, outside code spans and links.
            parts = re.split(r"(`[^`]*`|\[[^\]]*\]\([^)]*\))", line)
            line = "".join(part if i % 2 else re.sub(
                r"(?<![\w/.-])([A-Z][A-Z0-9-]*\.md)\b",
                lambda m: f"[{m[1]}]({target(doc, m[1])})" if (doc["repo"], m[1]) in sources else m[0], part)
                for i, part in enumerate(parts))
        lines.append(line)
    return "\n".join(lines) + "\n"

copied, coming = 0, []
for weight, doc in enumerate(docs, 1):
    text = sources.get((doc["repo"], doc["path"]))
    if text is None:
        coming.append(f"{doc['repo']}/{doc['path']}")
        continue
    text = re.sub(r"\A# .*\n+", "", text)
    meta = {
        "title": doc["title"],
        "description": doc["about"],
        "weight": weight,
        "template": "verge-doc.html",
    }
    extra = {"group": doc["group"], "source": f"{GITHUB}/{doc['repo']}/blob/HEAD/{doc['path']}", "repo": doc["repo"]}
    # A JSON string is a valid TOML basic string.
    head = "\n".join(f"{k} = {json.dumps(v)}" for k, v in meta.items())
    head += "\n[extra]\n" + "\n".join(f"{k} = {json.dumps(v)}" for k, v in extra.items())
    (out / f"{doc['name']}.md").write_text(f"+++\n{head}\n+++\n\n{rewrite(doc, text)}")
    copied += 1

print(f"copied {copied} docs; not written yet: {', '.join(coming) or 'none'}")
